import zipfile, re, json, concurrent.futures as cf, os
apks=json.load(open("/tmp/apks.json"))
model_re=re.compile(r'\.(tflite|mnn|onnx|npubin|dlc|caffemodel|pt|pth|pb|ai_model|bin|xmodel|kmodel|rknn|mlmodel|gguf|ort)$',re.I)
lib_re=re.compile(r'lib(.*(tensorflow|tflite|litert|nnapi|neural|mllite|onnx|pytorch|caffe|snpe|qnn|opencl|opencv|megvii|face|arcsoft|arcsoft|ai|mlkit|mediapipe|vision|image_enhance|imu|hdr|ais|scanner|ocr).*)\.so$',re.I)
hits={}
for a in apks:
    try:
        z=zipfile.ZipFile(a)
        names=z.namelist()
    except Exception as e:
        hits[a]=["ERR:"+str(e)]; continue
    h=[]
    for n in names:
        b=os.path.basename(n)
        if model_re.search(n) or lib_re.search(b):
            h.append(n)
    if h:
        hits[a]=h
    z.close()
json.dump(hits,open("/tmp/hits.json","w"))
print(len(hits))
for a,h in sorted(hits.items()):
    print("==",a.replace(R:="./"))
    for n in h[:25]: print("   ",n)
    if len(h)>25: print("    ...",len(h)-25,"more")

