import json, zipfile, os, re, concurrent.futures as cf, collections
apks=json.load(open("/tmp/apks.json"))
markers=[b"Lorg/tensorflow/lite",b"Lcom/google/mlkit",b"Lcom/google/android/gms/mlkit",b"Lcom/google/android/gms/vision",
 b"Lcom/google/android/libraries/vision",b"Lorg/pytorch",b"Lorg/onnxruntime",b"Lcom/qualcomm/qti/qnn",b"Lcom/qualcomm/snpe",
 b"Lcom/arcsoft",b"Lcom/megvii",b"Lcom/xiaomi/ai",b"Lcom/miui/ai",b"Lcom/mi/ai",b"Lmllite",b"Lcom/xiaomi/mllite",b"Lmediapipe",
 b"libtensorflowlite",b"libonnxruntime",b"tflite",b"NeuralNetworks",b"Lcom/google/ai",b"Landroid/media/ml",b"Lcom/google/android/apps/mlkit",
 b"SmartReply",b"TextClassifier",b"BarcodeScanner",b"ImageLabeler",b"FaceDetector",b"ObjectDetector",b"PoseDetector",b"EntityExtraction",
 b"Lcom/google/mlkit/vision",b"Lcom/google/mlkit/nl",b"mibrain",b"Lcom/miui/maml",b"Lcom/xiaomi/miui/ai"]
res={}
def scan(a):
    out=collections.Counter(); ms=set()
    try:
        z=zipfile.ZipFile(a)
    except Exception as e:
        return a,None
    for i in z.infolist():
        n=i.filename
        if not (n.endswith(".dex") or n.endswith(".arsc")): continue
        try: d=z.read(i)
        except Exception: continue
        for m in markers:
            if m in d: ms.add(m.decode())
    z.close()
    return a,sorted(ms)
with cf.ThreadPoolExecutor(16) as ex:
    for a,ms in ex.map(scan,apks):
        if ms: res[a]=ms
json.dump(res,open("/tmp/dexhits.json","w"))
print(len(res))

