import zipfile, re
R="/run/media/asdf/30620d0d-1e41-4d55-af08-b4de2fb9c517/xiaomi poco f4 system/"
def ss(apk):
    out=[]
    with zipfile.ZipFile(R+apk) as z:
        for i in z.infolist():
            if i.filename.endswith((".dex",)) or i.filename=="resources.arsc" or i.filename=="AndroidManifest.xml":
                out += re.findall(rb'[\x20-\x7e\x80-\xff]{2,}', z.read(i))
    return [s.decode('utf-8','ignore') for s in out]
a=ss("product/priv-app/MIUIAICR/MIUIAICR.apk")
pat=re.compile(r'(录音|通话|转写|字幕|摘要|认知|识别|扫描|抠图|隐私|模糊|美颜|场景|智能|本地|AI|miocr|ocr|segment|matting|privacy|blur|call)')
hits=sorted(set(x for x in a if pat.search(x)))
for s in hits[:250]: print("  ",s[:140])

